INSERT INTO "courts" ("court_id", "name", "level", "region") VALUES ('court_sh_mid', 'Shanghai No.2 Intermediate People Court', '', 'Shanghai');
INSERT INTO "courts" ("court_id", "name", "level", "region") VALUES ('court_sh_putuo', 'Shanghai Putuo District People Court', '', 'Shanghai');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_e552574c6c4c5773bbe9042a6fb69d36', '（2024）028412', 'Later handwritten will supported by original and witnesses', 'court_sh_mid', '', 'inheritance', '2024-09-12', 'Zhou v Zhou', 'A daughter produced the original handwritten will, two contemporaneous diary entries, and bank-signature samples.', 'The instrument contained a complete date and signature; a handwriting examiner found the body and signature consistent with verified samples.', 'The later instrument could alter an earlier typed will because its authorship, statutory form, and genuine intent were established together.', 'The later handwritten disposition governed the assets named in both instruments.', 'The first-instance distribution was adjusted for the overlapping assets.', '', 'inheritance, handwritten will, signature, full date, appraisal');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_0e7f4a1adc735e2ebcc75ee040184802', '（2023）010715328', 'Household allocation note treated as an investigative clue', 'court_sh_putuo', '', 'inheritance', '2023-11-03', 'Sun v Sun', 'A notebook page divided household items but carried neither a signature nor a complete date.', 'Relatives agreed that the handwriting resembled the decedent, while no witness saw the page being written and the original notebook was incomplete.', 'Informal statements may illuminate intent, yet they do not replace the execution elements required for a will.', 'The page was admitted as context but did not independently determine succession.', 'The statutory-succession claims were decided without treating the note as a will.', '', 'inheritance, family note, missing signature, incomplete date');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_30e91ef46e12535fac66c0c31d64a042', '（2024）01059671', 'Clinic encounters close to execution supported decision-making ability', 'court_sh_putuo', '', 'inheritance', '2024-05-28', 'Lu v Lu', 'The contested will was signed between two clinic visits documenting coherent conversation, medication management, and bill payment.', 'A stroke occurred fourteen months later; no witness described disorientation during the execution week.', 'Capacity had to be assessed at the signing date through contemporaneous medical and behavioral evidence rather than later decline alone.', 'The challenger did not prove lack of capacity at execution.', 'The will-validity claim was upheld, while an expense claim was remanded for calculation.', '', 'inheritance, testamentary capacity, contemporaneous clinic records');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_410f26f220af5067bef2fd496ed014a2', '（2022）0211603', 'Later cognitive screening did not establish earlier incapacity', 'court_sh_mid', '', 'inheritance', '2022-12-19', 'Qian v Qian', 'An MMSE score of 16 was recorded almost two years after a notarized testament.', 'The earlier notary video showed responsive answers, but the hospital retained no formal cognitive score for that earlier day.', 'A remote screening result was relevant context and required caution, but it could not alone prove the state of mind at an earlier execution.', 'Additional execution-period evidence was necessary to displace the notarized record.', 'The appeal challenging capacity was dismissed.', '', 'inheritance, MMSE, execution date, later decline');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_91b9694f2c185509852ce8dbb148ed99', '（2023）01064429', 'Neighbor recollections given limited weight on testamentary capacity', 'court_sh_putuo', '', 'inheritance', '2023-08-16', 'He v He', 'Two neighbors described missed appointments during the final winter but did not attend the signing eighteen months earlier.', 'One statement was based on conversations with another relative; the other identified no specific date of confusion.', 'Lay observations must be anchored to the relevant period and distinguished from hearsay about a different period.', 'The statements could corroborate decline only for the months they described.', 'The capacity challenge failed for lack of execution-date proof.', '', 'inheritance, neighbor statement, timing, hearsay');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_f9030fb67bc257069deb27bf25e2cc26', '（2024）01127215', 'Original document and comparison material required for handwriting appraisal', 'court_sh_putuo', '', 'inheritance', '2024-07-04', 'Wu v Wu', 'One party submitted a phone photograph of a disputed will and three photocopied signatures.', 'The original remained with a relative, while verified bank and housing records contained usable signatures from nearby years.', 'A reliable appraisal ordinarily requires the original instrument and authenticated comparison material with a documented custody chain.', 'The court ordered preservation and production before appointing an examiner.', 'The appraisal request was granted; validity was reserved.', '', 'inheritance, handwriting appraisal, original document, custody');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_649411bb8176532cb5e63d8a3ae84a81', '（2023）010418972', 'Care contribution analyzed separately from testamentary form', 'court_sh_putuo', '', 'inheritance', '2023-10-27', 'Fang v Fang', 'A son lived with the decedent for five years and paid documented nursing expenses.', 'The disputed note lacked one formal element, and the caregiver relied on his support history as an alternative basis for a larger share.', 'Support performance may affect statutory distribution or reimbursement, but it does not supply a missing will formality.', 'The court separated the expense and statutory-share issues from the instrument-validity issue.', 'Necessary expenses were partly reimbursed; the note was assessed on its own form.', '', 'inheritance, caregiver, reimbursement, statutory share');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_b7528db45d34557485378ce76c22c4fb', '（2025）021337', 'Identified estate deposit preserved during competing-will suit', 'court_sh_mid', '', 'inheritance', '2025-03-21', 'Gao v Gao', 'A bank reported an imminent release request against a specifically identified time deposit.', 'The applicant filed the competing instruments, account certificate, urgency evidence, and security within the court deadline.', 'Preservation was proportionate because the asset and maximum amount were clear and later enforcement could otherwise become difficult.', 'A temporary freeze was available without deciding which will ultimately controlled.', 'The preservation order was affirmed with a reduced secured amount.', '', 'inheritance, bank deposit, preservation, security');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_630b07d0b9cd593e8a052f42da234e71', '（2024）010910463', 'Dispute notation followed court acceptance in a succession case', 'court_sh_putuo', '', 'inheritance', '2024-06-14', 'Deng v Deng', 'An apartment transfer was recorded while a suit over two wills was pending.', 'The claimant presented the case-acceptance notice and a preservation ruling to the registry within the objection period.', 'Formal court materials connected the asserted succession dispute to the registered property and justified a temporary notation.', 'A private objection letter alone would not have established the procedural basis.', 'The request for notation and evidence preservation was supported.', '', 'inheritance, registry notation, court acceptance, apartment');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_1789b5df725e5ee0a4e796ca714214c3', '（2023）011522518', 'Medical disclosure limited during family mediation', 'court_sh_putuo', '', 'inheritance', '2023-12-08', 'Jiang v Jiang', 'A mediator proposed exchanging a complete five-year hospital chart in a dispute focused on one execution month.', 'The hospital could supply visit records for the narrower period through counsel and court channels.', 'Sensitive medical information should be limited to the purpose, relevant dates, and controlled recipients; mediation does not create blanket consent.', 'The exchange protocol was narrowed to the execution period and listed custodians.', 'The overbroad private-email request was denied.', '', 'inheritance, medical privacy, minimum necessary, mediation');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_3c748f63336c545487114b7bc26f7d44', '（2025）022981', 'Notarized testament compared with a later revocation document', 'court_sh_mid', '', 'inheritance', '2025-04-30', 'Ma v Ma', 'A notarized testament was followed by a signed letter revoking only the gift of a shop.', 'The notary archive contained no later filing, but witnesses and postal records supported the separate revocation letter.', 'Notarization did not prevent a later valid act from changing the overlapping disposition; the scope of revocation had to be read precisely.', 'The earlier testament remained effective for assets outside the later revocation.', 'The judgment was modified only as to the shop.', '', 'inheritance, notarized will, later revocation, overlapping assets');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_490a81a24bea5689b373b6bf9904852f', '（2022）010717844', 'Relative lacked authority to bind heir to immediate settlement', 'court_sh_putuo', '', 'inheritance', '2022-09-09', 'Xu v Xu', 'An uncle emailed acceptance of a cash waiver while the named heir was hospitalized.', 'No power of attorney or later ratification authorized the uncle to settle inheritance or release an apartment claim.', 'Waiver and disposition require informed consent from the right holder or a valid representative acting within authority.', 'The email did not bind the heir, though the payment could be returned.', 'The settlement-enforcement claim was dismissed.', '', 'inheritance, settlement authority, waiver, representation');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_b7064501a51659f5ba6000e8378daddf', '（2024）01106319', 'Photo metadata did not prove when a testament was executed', 'court_sh_putuo', '', 'inheritance', '2024-03-18', 'Tang v Tang', 'A phone folder showed that an image was imported on a particular day, but the paper itself displayed a different partial date.', 'The original paper could not initially be located and the photographer did not witness writing or signing.', 'File-system metadata may show image handling, not the date on which the underlying instrument was written or signed.', 'The party had to preserve the device and continue searching for the original.', 'The court deferred authenticity findings and ordered evidence preservation.', '', 'inheritance, photo metadata, execution date, original paper');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_4af86aa0e5cd5328b91f36dbc243156d', '（2023）010520306', 'Interim estate management preserved positions during mediation', 'court_sh_putuo', '', 'inheritance', '2023-05-12', 'Luo v Luo', 'The heirs agreed that rental income would remain in a joint supervised account while will issues were mediated.', 'The written protocol stated that no party accepted a final share and no apartment could be sold without unanimous written approval.', 'Temporary management arrangements can reduce loss without deciding merits or waiving contested succession positions.', 'The reservation language prevented the protocol from becoming a final distribution agreement.', 'The accounting terms were enforced and the merits claims continued.', '', 'inheritance, mediation, interim management, no waiver');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_72d411c51d1f5d26b301e9b50059a1a9', '（2025）01063022', 'Bank kept estate funds pending formal succession materials', 'court_sh_putuo', '', 'inheritance', '2025-02-26', 'Shen v Bank', 'One heir asked the bank to release a deceased customer deposit using a photocopied testament.', 'Another heir delivered a dispute notice, death certificate, and proof that a succession filing was being prepared.', 'The bank could maintain the status quo while requiring notarized succession materials or a court instrument, provided it treated claimants consistently.', 'No claimant had a unilateral right to immediate payment on the incomplete package.', 'The damages claim against the bank was rejected.', '', 'inheritance, bank release, dispute notice, deceased account');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_b092354292d453b6a699c4bf0357f8ea', '（2022）011214803', 'Documented final-care expenses supported a separate reimbursement award', 'court_sh_putuo', '', 'inheritance', '2022-11-25', 'Chen v Chen', 'A daughter submitted pharmacy invoices, nursing receipts, transport logs, and proof of payment for the final six months.', 'The siblings disputed inheritance shares but did not show that the expenses were gifts or outside necessary care.', 'Verified necessary expenses can be accounted for independently from the validity of a will and from any larger-share request.', 'The court reimbursed supported expenses before distributing the remaining estate.', 'The reimbursement claim was partly supported after duplicate receipts were excluded.', '', 'inheritance, care receipts, reimbursement, expense evidence');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_5227b66f97cf5e3098815f97c8ae39ec', '（2024）010411987', 'Mediation term sheet expressly reserved testamentary claims', 'court_sh_putuo', '', 'inheritance', '2024-10-15', 'Bai v Bai', 'The parties signed a term sheet for property maintenance and tax payment while awaiting an appraisal.', 'The document excluded final ownership, will validity, and any release of claims from the temporary arrangement.', 'Clear reservation language allowed practical cooperation without converting the term sheet into a succession settlement.', 'Payment of carrying costs did not admit the opposing will.', 'The temporary obligations were enforced; the inheritance action proceeded.', '', 'inheritance, mediation, reservation of rights, appraisal');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_e1b6ec0f71f25da0b97575c99d969dc9', '（2023）01098376', 'Private family letter was insufficient for registry objection', 'court_sh_putuo', '', 'inheritance', '2023-06-29', 'Peng v Registry', 'A claimant mailed the registry a family letter asserting that a transferred apartment belonged to an estate.', 'The packet included no case-acceptance notice, preservation ruling, notarized consent, or document connecting the claimant to the title.', 'A registry objection requires the procedural materials specified by law; an unverified private assertion does not create a notation by itself.', 'The registry could reject the incomplete packet without deciding inheritance merits.', 'The administrative challenge was dismissed.', '', 'inheritance, registry objection, court acceptance, private letter');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_capacity_medical_records', '（2024）010712651', 'Capacity challenge required an execution-period medical and witness chain', 'court_sh_putuo', '', 'inheritance', '2024-08-23', 'Han v Han', 'The challenger relied on a dementia diagnosis made sixteen months after a home-written testament.', 'Clinic notes from the execution month recorded independent conversation and payment, while a visiting nurse described intermittent fatigue but no disorientation on the signing day.', 'The court compared medical timing, medication effects, witness opportunity, and the complexity of the disposition rather than treating a later diagnosis as conclusive.', 'Capacity remained unresolved only where contemporaneous records conflicted; remote evidence alone carried limited weight.', 'The challenge was rejected for the real-property clause and remanded as to a later-added cash clause.', '', 'capacity, medical records, execution period, witness chain');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_holographic_missing_signature', '（2023）010517420', 'Unsigned Spring Festival allocation page did not displace prior testament', 'court_sh_putuo', '', 'inheritance', '2023-09-14', 'Yu v Yu', 'A page headed Spring Festival arrangements divided a shop and savings but ended without the writer signature and stated only lunar month and day.', 'The original notebook was produced, and handwriting evidence suggested the decedent wrote much of the body; no witness observed completion.', 'Authorship evidence did not cure the separate statutory requirements of signature and a complete year-month-day date for a self-written will.', 'The page remained relevant to family negotiations but could not revoke the earlier signed testament.', 'The claim that the page controlled the shop and savings was dismissed.', '', 'self-written will, missing signature, incomplete date, inheritance');
INSERT INTO "cases" ("case_id", "case_number", "title", "court_id", "case_type", "cause", "judgment_date", "parties", "summary", "facts", "reasoning", "holding", "ruling", "outcome", "keywords") VALUES ('case_transfer_preservation_estate', '（2025）024216', 'Apartment preserved after disputed succession transfer', 'court_sh_mid', '', 'inheritance', '2025-07-11', 'Nie v Nie', 'An apartment was transferred to one heir using a succession certificate while another heir contested the instrument supporting that certificate.', 'The challenger promptly filed suit, identified the registered unit and potential onward sale, and offered security; no evidence showed an arm-length purchaser had acquired it.', 'Preservation protected the recoverability of the specific apartment without resolving the competing-instrument merits, and the registry notation depended on formal court documents.', 'The transfer record could remain while sale and mortgage were temporarily restricted.', 'The preservation ruling and registry notice were affirmed.', '', 'property preservation, succession transfer, registry notation, court order');
INSERT INTO "statutes" ("statute_id", "name", "short_name", "issuer", "effective_date", "status", "summary") VALUES ('stat_civil_inheritance', '（）', '', '', '2021-01-01', '', 'Rules on statutory succession, testamentary forms, revocation, genuine intent, civil capacity, and distribution among heirs.');
INSERT INTO "statutes" ("statute_id", "name", "short_name", "issuer", "effective_date", "status", "summary") VALUES ('stat_property_preservation', '（）', '', '', '2024-01-01', '', 'Procedural rules for pre-suit and in-suit preservation, security, urgency, scope, and enforcement of preservation rulings.');
INSERT INTO "statute_articles" ("article_id", "statute_id", "article_no", "seq", "heading", "text") VALUES ('art_capacity', 'stat_civil_inheritance', 'Article 1143', 1143, 'Capacity and genuine intent', 'A will made by a person without or with limited civil capacity is invalid; a will must express genuine intent.');
INSERT INTO "statute_articles" ("article_id", "statute_id", "article_no", "seq", "heading", "text") VALUES ('art_holographic_form', 'stat_civil_inheritance', 'Article 1134', 1134, 'Self-written will form', 'A self-written will must be written by the testator, signed by the testator, and indicate the year, month, and day.');
INSERT INTO "statute_articles" ("article_id", "statute_id", "article_no", "seq", "heading", "text") VALUES ('art_preservation', 'stat_property_preservation', 'Article 101', 101, 'Preservation', 'If conduct may make judgment difficult to enforce, preservation measures may be requested with evidence and security where required.');
INSERT INTO "statute_articles" ("article_id", "statute_id", "article_no", "seq", "heading", "text") VALUES ('art_support_share', 'stat_civil_inheritance', 'Article 1130', 1130, 'Support contribution', 'An heir who fulfilled main support duties may receive more when inheritance is statutory or when valid-will gaps remain.');
INSERT INTO "statute_articles" ("article_id", "statute_id", "article_no", "seq", "heading", "text") VALUES ('art_will_later_valid', 'stat_civil_inheritance', 'Article 1142', 1142, 'Later valid will controls', 'After several wills exist, the last valid will controls; notarization alone does not give automatic priority after Civil Code.');
