INSERT INTO cases VALUES ('case_est_membership','（2023）01054312','Fitness membership refund','court_sh_changning','','','2023-08-17','Liu v. Fit House','A relocated gym disputed refund of unused months.','The new location added substantial commute time and the contract lacked a relocation clause.','Material change of performance place supported partial termination.','Unused service value was refundable after deducting consumed benefits.','Defendant refunded the unused balance.','','membership,relocation,refund');
INSERT INTO cases VALUES ('case_est_photo_license','（2024）01062287','Photo license scope dispute','court_sh_jingan','','','2024-05-09','Studio v. Retailer','Product photographs licensed for one campaign remained online after the campaign ended.','Email terms limited time and channel; later use was outside the written license.','Continued commercial display infringed the reproduction and information-network rights.','Damages reflected duration, traffic, and licensing history.','Retailer removed images and paid damages.','','photograph,license,online display');
INSERT INTO cases VALUES ('case_est_salary','（2024）013762','Quarterly bonus calculation','court_sh_no1_est','','','2024-07-18','Design Firm v. Wu','The parties disputed bonus treatment for an employee leaving mid-quarter.','Payroll history showed consistent monthly proration for prior departures.','A stable compensation practice formed part of contract performance.','The bonus used actual months and the confirmed rating.','The first-instance payment order was affirmed.','','bonus,payroll,practice');
INSERT INTO cases VALUES ('case_est_platform','（2022）01059821','Online order record dispute','court_sh_changning','','','2022-11-30','Zhao v. Marketplace','A merchant denied the specification displayed on the archived order page.','Platform logs and confirmation email matched the buyer screenshot.','Stored transaction information reliably established the contract description.','The delivered item failed to match the agreed specification.','Merchant replaced the item and paid shipping.','','platform log,order page,specification');
INSERT INTO cases VALUES ('case_est_privacy','（2023）01066140','Building visitor log disclosure','court_sh_jingan','','','2023-12-14','Sun v. Property Service','A visitor ledger containing phone numbers was left at an unattended desk.','Photographs and inspection notes showed unrestricted access during the afternoon.','The controller lacked basic safeguards for contact and visit information.','Corrective measures and reasonable evidence costs were recoverable.','Property company apologized and paid evidence costs.','','visitor log,personal information,safeguard');
INSERT INTO cases VALUES ('case_est_property_fee','（2021）01057336','Vacant apartment service fee','court_sh_changning','','','2021-10-22','Property Co. v. Huang','An owner withheld all fees because the apartment was vacant.','Security, elevator, cleaning, and common-energy records showed building-wide service.','Vacancy did not erase payment duty, though documented service defects justified reduction.','A limited reduction reflected missed corridor cleaning.','Owner paid most arrears and reduced liquidated damages.','','property fee,vacancy,service record');
INSERT INTO cases VALUES ('case_est_mediation','（2022）015041','Payment mediation confirmation','court_sh_no1_est','','','2022-09-06','Qian v. Zhou','After community mediation, one party denied the signed installment schedule.','Identity verification and contemporaneous messages confirmed voluntary execution.','A valid mediation agreement bound the parties absent fraud or coercion.','Outstanding installments remained payable under the agreement.','The repayment schedule was confirmed.','','mediation,installments,signature');
INSERT INTO cases VALUES ('case_est_delivery','（2024）142','Courier damage retrial review','court_sh_high_est','','','2024-09-12','Courier Co. v. Tang','A courier challenged liability for a damaged framed print.','Pickup images showed intact packaging and delivery video showed a crushed corner.','Existing evidence supported damage during custody; no new evidence justified retrial.','Repair cost was tied to a paid conservation invoice.','Retrial petition was rejected.','','courier,custody,repair invoice');
