INSERT INTO cases VALUES ('case_est_art_storage','（2024）01093527','Framed artwork storage damage','court_sh_hongkou_est','','','2024-06-28','Collector v. Storage Studio','A framed photograph developed moisture marks during paid storage.','Intake images showed a clean print, while humidity logs contained a five-day gap during an air-conditioning outage.','A professional custodian should maintain the agreed environmental conditions and explain missing monitoring records.','Conservation treatment cost was supported by a paid specialist invoice.','The studio paid treatment costs and refunded storage fees for the affected month.','','art storage,humidity log,conservation');
INSERT INTO cases VALUES ('case_est_ticket_cancel','（2023）01099064','Cancelled chamber concert ticket','court_sh_hongkou_est','','','2023-12-19','Gu v. Concert Organizer','The organizer cancelled a quartet performance and offered only venue credit.','The ticket terms identified a specific date and ensemble, and the buyer rejected a different program.','When the agreed performance cannot occur, venue credit does not replace a monetary refund without consent.','The ticket price and separately charged booking fee were both refundable.','The organizer returned the full payment.','','concert ticket,cancellation,refund');
INSERT INTO saved_cases VALUES ('saved_est_art_storage','chen_yu','case_est_art_storage','Environmental logs and intake photographs establish the custody interval.','2025-10-26T14:08:00+08:00');
